# Compute girth via BFS
def girth(G):
    g = float('inf')
    for src in G.nodes():
        dist = {src: 0}
        parent = {src: None}
        from collections import deque
        q = deque([src])
        while q:
            u = q.popleft()
            for v in G.neighbors(u):
                if v not in dist:
                    dist[v] = dist[u]+1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    cyc = dist[u] + dist[v] + 1
                    if cyc < g:
                        g = cyc
    return g

print("girth:", girth(G))

# Check 3-colorability with a greedy/backtracking
def three_color(G):
    nodes = list(G.nodes())
    color = {}
    def bt(i):
        if i == len(nodes):
            return True
        v = nodes[i]
        used = {color[u] for u in G.neighbors(v) if u in color}
        for c in range(3):
            if c not in used:
                color[v] = c
                if bt(i+1):
                    return True
                del color[v]
        return False
    if bt(0):
        return color
    return None

c = three_color(G)
print("3-colorable:", c is not None)
print("colors:", c)

