        edges.add((i, (i+1)%n) if i < (i+1)%n else ((i+1)%n, i))
    for i in range(n):
        j = (i + L[i % len(L)]) % n
        edges.add((min(i,j), max(i,j)))
    adj = {i:set() for i in range(n)}
    for u,v in edges: adj[u].add(v); adj[v].add(u)
    # degree check
    degs = [len(adj[i]) for i in range(n)]
    # girth
    from collections import deque
    g = 1<<30
    for src in range(n):
        dist={src:0}; parent={src:-1}
        q=deque([src])
        while q:
            u=q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v]=dist[u]+1; parent[v]=u; q.append(v)
